import re

def check_jpeg_exif_rights(path):
    """Extract copyright/artist from JPEG EXIF"""
    data = Path(path).read_bytes()
    pos = 2

    while pos < len(data) - 1:
        if data[pos] != 0xFF:
            break
        marker = data[pos + 1]

        if marker == 0xD9:
            break
        if marker in (0x01, 0xD0, 0xD1, 0xD2, 0xD3, 0xD4, 0xD5, 0xD6, 0xD7, 0xD8):
            pos += 2
            continue

        if pos + 4 > len(data):
            break

        import struct
        seg_len = struct.unpack('>H', data[pos+2:pos+4])[0]
        seg_data = data[pos+4:pos+2+seg_len]

        if marker == 0xE1 and seg_data.startswith(b'Exif\x00\x00'):
            exif_str = seg_data.decode('latin-1', errors='ignore')
            # Look for copyright/artist
            if 'copyright' in exif_str.lower() or '©' in exif_str:
                print(f"  {path}: EXIF contains copyright info")
                return True

        pos += 2 + seg_len

    return False

